            count_digit = 0;
            count_step = 0;
            carry = 0;
            tens_digit = 0;
            current_digit = 0;
            ones_digit = 0;
        end else begin
            // Increment counting steps
            count_step++;

            // If counting step exceeds 3, set carry to 1
            if (count_step == 3) begin
                carry = 1;
